import{_ as s,o as p,c as e,a2 as t}from"./chunks/framework.EUByU7Iq.js";const z=JSON.parse('{"title":"悼乱","description":"","frontmatter":{"title":"悼乱","date":"2026-11-24T00:00:00.000Z","seq":62,"categories":["美文","楚辞"],"collection":"《楚辞》","tags":["楚辞","先秦"],"poem":true,"poem_quote":false,"author":"王逸","source_book":"楚辞","prev":{"text":"遭厄","link":"/blogs/楚辞/遭厄.html"},"next":{"text":"伤时","link":"/blogs/楚辞/伤时.html"}},"headers":[],"relativePath":"blogs/楚辞/悼乱.md","filePath":"blogs/楚辞/悼乱.md"}'),o={name:"blogs/楚辞/悼乱.md"};function l(n,a,c,m,r,_){return p(),e("div",null,[...a[0]||(a[0]=[t('<h1 id="悼乱" tabindex="-1">悼乱 <a class="header-anchor" href="#悼乱" aria-label="Permalink to &quot;悼乱&quot;">​</a></h1><p class="poem-meta">先秦 · 王逸　·　九思</p><div class="poem"><p class="poem-stanza">嗟嗟兮悲夫，殽乱兮纷挐。</p><p class="poem-stanza">茅丝兮同综，冠屦兮共絇。</p><p class="poem-stanza">督万兮侍宴，周邵兮负刍。</p><p class="poem-stanza">白龙兮见射，灵龟兮执拘。</p><p class="poem-stanza">仲尼兮困厄，邹衍兮幽囚。</p><p class="poem-stanza">伊余兮念兹，奔遁兮隐居。</p><p class="poem-stanza">将升兮高山，上有兮猴猿。</p><p class="poem-stanza">欲入兮深谷，下有兮虺蛇。</p><p class="poem-stanza">左见兮鸣鵙，右睹兮呼枭。</p><p class="poem-stanza">惶悸兮失气，踊跃兮距跳。</p><p class="poem-stanza">便旋兮中原，仰天兮增叹。</p><p class="poem-stanza">菅蒯兮楙莽，雚苇兮仟眠。</p><p class="poem-stanza">鹿蹊兮躖躖，貒貉兮蟫蟫。</p><p class="poem-stanza">鹯鹞兮轩轩，鹑鹌兮甄甄。</p><p class="poem-stanza">哀我兮寡独，靡有兮齐伦。</p><p class="poem-stanza">意欲兮沉吟，迫日兮黄昏。</p><p class="poem-stanza">玄鹤兮高飞，曾逝兮青冥。</p><p class="poem-stanza">鶬鶊兮喈喈，山鹊兮嚶嚶。</p><p class="poem-stanza">鸿鸬兮振翅，归雁兮于征。</p><p class="poem-stanza">吾志兮觉悟，怀我兮圣京。</p><p class="poem-stanza">垂屣兮将起，跓俟兮硕明。</p></div>',3)])])}const d=s(o,[["render",l]]);export{z as __pageData,d as default};
